// Client credentials contra identity (seguridad-y-sso.md §6.2); cachea en static data hasta 30 s antes de exp.
const sd = $getWorkflowStaticData('global');
const now = Math.floor(Date.now() / 1000);
if (sd.token && sd.exp && sd.exp - 30 > now) return [{ json: { token: sd.token, exp: sd.exp, cached: true } }];
const res = await this.helpers.httpRequest({
  method: 'POST', url: ($env.BANDADA_IDENTITY_INTERNAL_URL || 'http://identity-service:7001') + '/api/v1/auth/service-token',
  body: { clientId: $env.N8N_SERVICE_CLIENT_ID, clientSecret: $env.N8N_SERVICE_CLIENT_SECRET, scopes: ['internal:read', 'internal:write'] },
  json: true, timeout: 10000,
});
sd.token = res.accessToken; sd.exp = now + (res.expiresIn || 300);
return [{ json: { token: sd.token, exp: sd.exp, cached: false } }];
